//! Deterministic compilation of a [`Config`] into OpenSSH configuration and
//! Graphviz DOT.

use crate::{
    config::{Config, Host},
    resolver::{self, ResolvedHost, Resolver},
    util,
};
use anyhow::{Context, Result, ensure};
use sha1::{Digest, Sha1};
use std::{collections::BTreeSet, fmt::Write};

/// First line of every generated file; sshweave refuses to overwrite files
/// that do not start with it.
pub const HEADER: &str = "# Generated by sshweave; DO NOT EDIT.\n";

/// Quotes a value for OpenSSH configuration.
fn ssh_quote(input: &str) -> Result<String> {
    util::single_line(input)?;
    Ok(format!(
        "\"{}\"",
        input.replace('\\', "\\\\").replace('"', "\\\"")
    ))
}

/// Returns whether a host key or alias is rendered as an OpenSSH `Host` pattern.
/// Regular expressions cannot be expressed in OpenSSH and are materialized instead.
fn is_glob(name: &str) -> bool {
    resolver::is_pattern(name) && !name.starts_with("regex:")
}

/// Emits raw `[ssh]` options.
fn ssh_options(output: &mut String, options: &Host) -> Result<()> {
    for (key, value) in &options.ssh {
        for line in value.lines() {
            let line = util::expand_env(&line)?;
            util::single_line(&line)?;
            // Values are OpenSSH argument expressions (e.g. LocalForward "8080 localhost:80"),
            // so they are emitted verbatim rather than quoted.
            writeln!(output, "  {key} {line}")?;
        }
    }
    Ok(())
}

/// Emits one `Host` stanza. For wildcard stanzas, the hostname keeps OpenSSH's
/// `%h` token instead of a resolved value.
fn stanza(
    output: &mut String,
    host: &ResolvedHost,
    wildcard: bool,
    exclusions: &[String],
) -> Result<()> {
    write!(output, "\nHost {}", host.name)?;
    for exclusion in exclusions {
        write!(output, " {exclusion}")?;
    }
    output.push('\n');
    if let Some(comment) = &host.options.comment {
        for line in comment.lines() {
            writeln!(output, "  # {line}")?;
        }
    }
    let hostname = if wildcard {
        host.options
            .hostname
            .as_deref()
            .unwrap_or("%h")
            .replace("%n", "%h")
    } else {
        host.hostname.clone()
    };
    ensure!(
        !hostname.contains(['{', '}']),
        "capture substitution requires a concrete target"
    );
    writeln!(
        output,
        "  HostName {}\n  User {}\n  Port {}",
        ssh_quote(&util::expand_env(&hostname)?)?,
        ssh_quote(&host.user)?,
        host.port
    )?;
    if let Some(seconds) = host.options.connect_timeout {
        writeln!(output, "  ConnectTimeout {seconds}")?;
    }
    ssh_options(output, &host.options)
}

/// Emits the `Host *` stanza carrying `[defaults]`, excluding every name that
/// already has its own stanza.
fn defaults_stanza(output: &mut String, defaults: &Host, exclusions: &[String]) -> Result<()> {
    writeln!(output, "\nHost * {}", exclusions.join(" "))?;
    ssh_options(output, defaults)?;
    if let Some(user) = &defaults.user {
        writeln!(output, "  User {}", ssh_quote(&util::expand_env(user)?)?)?;
    }
    if let Some(port) = defaults.port {
        writeln!(output, "  Port {port}")?;
    }
    if let Some(seconds) = defaults.connect_timeout {
        writeln!(output, "  ConnectTimeout {seconds}")?;
    }
    if let Some(hostname) = &defaults.hostname {
        writeln!(
            output,
            "  HostName {}",
            ssh_quote(&util::expand_env(&hostname.replace("%n", "%h"))?)?
        )?;
    }
    Ok(())
}

/// Emits the final catch-all stanza routing every connection through sshweave.
fn proxy_command_stanza(
    output: &mut String,
    config: &Config,
    automatic_rewrite: bool,
) -> Result<()> {
    let binary = config.binary()?.to_string_lossy().into_owned();
    let source = config
        .source
        .to_str()
        .context("configuration path is not UTF-8")?;
    ensure!(
        !binary.contains('%') && !source.contains('%'),
        "paths used in ProxyCommand cannot contain %"
    );
    let command = format!(
        "{} --config {} connect --port %p --user %r {}-- %n",
        shell_words::quote(&binary),
        shell_words::quote(source),
        if automatic_rewrite {
            ""
        } else {
            "--no-rewrite "
        }
    );
    // ProxyCommand retains its shell quoting; unlike normal SSH values, do not quote the whole line.
    util::single_line(&command)?;
    writeln!(output, "\nHost *\n  ProxyCommand {command}")?;
    Ok(())
}

/// Prefix of the generated line carrying the input and content fingerprints.
const DIGEST_PREFIX: &str = "# digest ";

/// Fingerprints every input that affects [`ssh_config`]: the sshweave version,
/// loaded source files, materialized targets, the rewrite mode, the
/// ProxyCommand binary, and the environment variables used during rendering.
pub fn input_digest(
    config: &Config,
    known: &BTreeSet<String>,
    automatic_rewrite: bool,
) -> Result<String> {
    let mut digest = Sha1::new();
    let mut field = |value: &[u8]| {
        digest.update(value.len().to_le_bytes());
        digest.update(value);
    };
    field(env!("CARGO_PKG_VERSION").as_bytes());
    field(config.source_digest().as_bytes());
    field(&[u8::from(automatic_rewrite)]);
    field(config.binary()?.to_string_lossy().as_bytes());
    for target in known {
        field(target.as_bytes());
    }
    for name in ["HOME", "USER"]
        .into_iter()
        .chain(config.env_references().iter().map(String::as_str))
    {
        field(name.as_bytes());
        match std::env::var_os(name) {
            Some(value) => field(value.to_string_lossy().as_bytes()),
            None => field(&[]),
        }
    }
    Ok(util::hex(&digest.finalize()))
}

/// Returns whether `text` is a managed file generated from inputs matching
/// `inputs` and left unmodified since, so it can be reused without rendering.
pub fn is_current(text: &str, inputs: &str) -> bool {
    let Some(rest) = text.strip_prefix(HEADER) else {
        return false;
    };
    let mut offset = 0;
    for line in rest.split_inclusive('\n') {
        offset += line.len();
        if let Some(value) = line.strip_prefix(DIGEST_PREFIX) {
            return value
                .trim_end()
                .split_once(' ')
                .is_some_and(|(input, content)| {
                    input == inputs
                        && content == util::hex(&Sha1::digest(&rest.as_bytes()[offset..]))
                });
        }
        if !line.starts_with('#') {
            break;
        }
    }
    false
}

/// Renders the complete OpenSSH configuration.
///
/// Layout: concrete hosts (configured names plus `known` materialized targets
/// and every gateway they route through), then glob patterns excluding those
/// concrete names, then `[defaults]`, then the sshweave ProxyCommand. Concrete
/// names are excluded from wildcard stanzas so repeatable options such as
/// `IdentityFile` are not accumulated twice by OpenSSH.
pub fn ssh_config(
    config: &Config,
    known: &BTreeSet<String>,
    automatic_rewrite: bool,
) -> Result<String> {
    ssh_config_with(&config.resolver()?, known, automatic_rewrite)
}

/// Like [`ssh_config`], reusing an already compiled [`Resolver`].
pub fn ssh_config_with(
    resolver: &Resolver<'_>,
    known: &BTreeSet<String>,
    automatic_rewrite: bool,
) -> Result<String> {
    let config = resolver.config();
    let mut output = String::new();
    let mut names = resolver.concrete_names();
    names.extend(known.iter().cloned());
    let names = resolver.route_targets(names)?;
    for name in &names {
        stanza(&mut output, &resolver.resolve(name)?, false, &[])?;
    }
    let mut exclusions: Vec<String> = names.iter().map(|name| format!("!{name}")).collect();
    let globs: Vec<&String> = config
        .document
        .hosts
        .iter()
        .flat_map(|(pattern, host)| std::iter::once(pattern).chain(&host.aliases))
        .filter(|pattern| is_glob(pattern))
        .collect();
    for pattern in &globs {
        let resolved = resolver.resolve_inner(pattern)?;
        stanza(&mut output, &resolved, true, &exclusions)?;
    }
    exclusions.extend(globs.iter().map(|pattern| format!("!{pattern}")));
    defaults_stanza(&mut output, resolver.defaults(), &exclusions)?;
    proxy_command_stanza(&mut output, config, automatic_rewrite)?;
    Ok(format!(
        "{HEADER}# sshweave {}\n{DIGEST_PREFIX}{} {}\n{output}",
        env!("CARGO_PKG_VERSION"),
        input_digest(config, known, automatic_rewrite)?,
        util::hex(&Sha1::digest(output.as_bytes()))
    ))
}

/// Renders gateway, proxy, alias, and inheritance relationships as Graphviz DOT.
pub fn graphviz(config: &Config) -> Result<String> {
    /// DOT accepts JSON string syntax for quoted identifiers.
    fn quoted(s: &str) -> Result<String> {
        Ok(serde_json::to_string(s)?)
    }
    /// Maps an `inherits` entry to its node name; templates get a `template:` prefix.
    fn parent_node(config: &Config, parent: &str) -> String {
        if let Some(name) = parent.strip_prefix("host:") {
            name.to_owned()
        } else if !parent.starts_with("template:") && config.document.templates.contains_key(parent)
        {
            format!("template:{parent}")
        } else {
            parent.to_owned()
        }
    }
    fn inherits_edge(output: &mut String, child: &str, parent: &str) -> Result<()> {
        writeln!(
            output,
            "  {} -> {} [style=dashed,label=\"inherits\"];",
            quoted(child)?,
            quoted(parent)?
        )?;
        Ok(())
    }

    let resolver = config.resolver()?;
    let mut output = String::from("digraph sshweave {\n  rankdir=LR;\n");
    for name in config.document.proxies.keys() {
        writeln!(
            output,
            "  {} [shape=box];",
            quoted(&format!("proxy:{name}"))?
        )?;
    }
    for (name, host) in &config.document.templates {
        let node = format!("template:{name}");
        writeln!(output, "  {} [shape=box,style=dashed];", quoted(&node)?)?;
        for parent in &host.inherits {
            inherits_edge(&mut output, &node, &parent_node(config, parent))?;
        }
    }
    for (name, host) in &config.document.hosts {
        writeln!(output, "  {} [shape=ellipse];", quoted(name)?)?;
        let resolved = resolver.resolve_inner(name)?;
        if let Some(proxy) = &resolved.options.proxy {
            writeln!(
                output,
                "  {} -> {} [style=dotted,label=\"proxy\"];",
                quoted(name)?,
                quoted(&format!("proxy:{proxy}"))?
            )?;
        }
        for gateway in resolved.routes().into_iter().filter(|g| g != "direct") {
            writeln!(
                output,
                "  {} -> {} [label={}];",
                quoted(name)?,
                quoted(&gateway)?,
                quoted(&format!("gateway ({})", resolved.gateway_strategy.as_str()))?
            )?;
        }
        for parent in &host.inherits {
            inherits_edge(&mut output, name, &parent_node(config, parent))?;
        }
        for alias in &host.aliases {
            writeln!(
                output,
                "  {} -> {} [style=dotted,label=\"alias\"];",
                quoted(alias)?,
                quoted(name)?
            )?;
        }
    }
    output.push_str("}\n");
    Ok(output)
}
